function out(array $p,int $s=200):void{http_response_code($s);echo json_encode($p,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function fail(string $m,int $s=400):void{out(['error'=>$m],$s);}
function body():array{$d=json_decode(file_get_contents('php://input')?:'{}',true);if(!is_array($d))fail('Invalid JSON body.');return $d;}
function now_ms():int{return (int)round(microtime(true)*1000);}
function rid(int $b=12):string{return rtrim(strtr(base64_encode(random_bytes($b)),'+/','-_'),'=');}
function cut(string $v,int $n):string{return function_exists('mb_substr')?mb_substr($v,0,$n):substr($v,0,$n);}
function clean_name($v):string{$s=trim(preg_replace('/[\x00-\x1F\x7F]/u','',strval($v)));if($s==='')fail('Player name is required.');return cut($s,24);}
function clean_text($v):string{$s=trim(preg_replace('/[\x00-\x1F\x7F]/u',' ',strval($v)));return cut($s,240);}
function code6($v):string{$s=strtoupper(trim(strval($v)));if(!preg_match('/^[A-Z0-9]{6}$/',$s))fail('A valid 6-character room code is required.');return $s;}
function room_code():string{$a='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';$s='';for($i=0;$i<6;$i++)$s.=$a[random_int(0,strlen($a)-1)];return $s;}

$root=dirname(__DIR__,2).'/wp-load.php';$useWp=is_file($root);if($useWp)require_once $root;
function store_get(string $k){global $useWp;if($useWp)return get_transient($k);$p=sys_get_temp_dir().'/'.$k.'.json';if(!is_file($p))return false;$d=json_decode(file_get_contents($p),true);if(!is_array($d)||($d['_expires']??0)<time()){@unlink($p);return false;}unset($d['_expires']);return $d;}
function store_set(string $k,array $v,int $ttl=BOB_TTL):void{global $useWp;if($useWp){set_transient($k,$v,$ttl);return;}$v['_expires']=time()+$ttl;file_put_contents(sys_get_temp_dir().'/'.$k.'.json',json_encode($v),LOCK_EX);}
function room_get(string $c):array{$r=store_get('bob2_room_'.$c);if(!$r)fail('Room not found or expired.',404);return $r;}
function room_save(array &$r):void{$r['updatedAt']=now_ms();$r['revision']=intval($r['revision']??0)+1;store_set('bob2_room_'.$r['code'],$r);foreach($r['players'] as $p)store_set('bob2_player_'.$p['id'],['code'=>$r['code'],'token'=>$p['token']],BOB_TTL);}
function with_lock(string $code,callable $fn){$path=sys_get_temp_dir().'/bob2_lock_'.$code.'.lck';$h=fopen($path,'c');if(!$h)fail('Room lock unavailable.',503);if(!flock($h,LOCK_EX))fail('Room lock unavailable.',503);try{return $fn();}finally{flock($h,LOCK_UN);fclose($h);}}
function presence_touch(string $id):void{store_set('bob2_presence_'.$id,['seen'=>now_ms()],90);}
function presence_alive(string $id):bool{return store_get('bob2_presence_'.$id)!==false;}
function rate_limit(string $scope,int $limit,int $seconds):void{$ip=$_SERVER['REMOTE_ADDR']??'unknown';$key='bob2_rl_'.$scope.'_'.substr(hash('sha256',$ip),0,20);$r=store_get($key);$count=is_array($r)?intval($r['count']??0):0;if($count>=$limit)fail('Too many requests. Try again shortly.',429);store_set($key,['count'=>$count+1],$seconds);}

