function shuffle_idx(int $n):array{$a=range(0,$n-1);for($i=$n-1;$i>0;$i--){$j=random_int(0,$i);[$a[$i],$a[$j]]=[$a[$j],$a[$i]];}return $a;}
function player_new(string $name,bool $host):array{return ['id'=>rid(),'token'=>rid(24),'name'=>$name,'host'=>$host,'active'=>true,'score'=>0,'streak'=>0,'bestStreak'=>0,'doubleUsed'=>false,'vote'=>null,'voteDouble'=>false,'joinedAt'=>now_ms()];}
function pidx(array $r,string $id):int{foreach($r['players'] as $i=>$p)if($p['id']===$id)return $i;return -1;}
function auth_room(array $r):int{$pid=$_SERVER['HTTP_X_PLAYER_ID']??'';$tok=$_SERVER['HTTP_X_PLAYER_TOKEN']??'';if(!$pid||!$tok)fail('Player session required.',401);$i=pidx($r,$pid);if($i<0||!hash_equals($r['players'][$i]['token'],$tok))fail('Invalid player session.',401);presence_touch($pid);return $i;}
function active_players(array $r):array{return array_values(array_filter($r['players'],fn($p)=>!empty($p['active'])));}
function all_voted(array $r):bool{foreach($r['players'] as $p)if(!empty($p['active'])&&($p['vote']??null)===null)return false;return count(active_players($r))>=BOB_MIN_PLAYERS;}
function current_card(array $r):array{$deck=cards();$idx=$r['deckOrder'][$r['round']]??null;if($idx===null||!isset($deck[$idx]))fail('Card deck is out of sync.',500);return $deck[$idx];}
function system_msg(array &$r,string $t):void{$r['chat'][]=['id'=>rid(8),'kind'=>'system','text'=>$t,'at'=>now_ms()];if(count($r['chat'])>80)$r['chat']=array_slice($r['chat'],-80);}
function transfer_host(array &$r):void{foreach($r['players'] as &$p)$p['host']=false;unset($p);$new=null;foreach($r['players'] as $i=>$p)if(!empty($p['active'])&&presence_alive($p['id'])){$new=$i;break;}if($new===null)foreach($r['players'] as $i=>$p)if(!empty($p['active'])){$new=$i;break;}if($new!==null){$r['players'][$new]['host']=true;$r['hostId']=$r['players'][$new]['id'];system_msg($r,$r['players'][$new]['name'].' is now the host.');}}
function begin_round(array &$r):void{foreach($r['players'] as &$p){$p['vote']=null;$p['voteDouble']=false;}unset($p);$r['status']='voting';$r['roundSummary']=null;$r['voteEndsAt']=$r['voteSeconds']===0?null:now_ms()+($r['voteSeconds']*1000);$r['revealEndsAt']=null;$r['lastEvent']=['id'=>rid(8),'type'=>'round-start','round'=>$r['round']+1];}
function reveal_round(array &$r):void{if($r['status']!=='voting')return;$c=current_card($r);$bud=0;$bluff=0;$correct=0;$active=0;foreach($r['players'] as &$p){if(empty($p['active']))continue;$active++;if($p['vote']==='BUD')$bud++;if($p['vote']==='BLUFF')$bluff++;$ok=$p['vote']!==null&&$p['vote']===$c['answer'];if($ok)$correct++;$dbl=!empty($p['voteDouble']);$delta=$dbl?($ok?2:-1):($ok?1:0);$p['score']+=$delta;if($ok){$p['streak']++;$p['bestStreak']=max($p['bestStreak'],$p['streak']);}else{$p['streak']=0;}if($dbl)$p['doubleUsed']=true;}unset($p);$r['roundSummary']=['budVotes'=>$bud,'bluffVotes'=>$bluff,'correct'=>$correct,'active'=>$active];$r['status']='reveal';$r['revealStartedAt']=now_ms();$r['revealEndsAt']=$r['autoAdvance']?now_ms()+($r['revealSeconds']*1000):null;$r['lastEvent']=['id'=>rid(8),'type'=>'round-reveal','answer'=>$c['answer'],'round'=>$r['round']+1];}
function finish_game(array &$r,string $reason='complete'):void{$r['status']='finished';$r['finishReason']=$reason;$r['voteEndsAt']=null;$r['revealEndsAt']=null;$r['lastEvent']=['id'=>rid(8),'type'=>'game-finished','reason'=>$reason];}
function next_round(array &$r):void{if($r['status']!=='reveal')return;$r['round']++;if($r['round']>=$r['roundLimit']){finish_game($r);return;}begin_round($r);}
function advance(array &$r):bool{$changed=false;$now=now_ms();if($r['status']==='voting'&&(all_voted($r)||($r['voteEndsAt']!==null&&$r['voteEndsAt']<=$now))){reveal_round($r);$changed=true;}if($r['status']==='reveal'&&$r['autoAdvance']&&$r['revealEndsAt']!==null&&$r['revealEndsAt']<=$now){next_round($r);$changed=true;}return $changed;}
function public_player(array $p,string $status,bool $isMe):array{$x=['id'=>$p['id'],'name'=>$p['name'],'host'=>$p['host'],'active'=>$p['active'],'score'=>$p['score'],'streak'=>$p['streak'],'bestStreak'=>$p['bestStreak'],'doubleAvailable'=>!$p['doubleUsed'],'hasVoted'=>$p['vote']!==null];if($isMe||$status==='reveal'||$status==='finished'){$x['vote']=$p['vote'];$x['usedDouble']=$p['voteDouble'];}return $x;}
function standings(array $ps):array{$a=array_map(fn($p)=>['id'=>$p['id'],'name'=>$p['name'],'score'=>$p['score'],'bestStreak'=>$p['bestStreak'],'active'=>$p['active']],$ps);usort($a,fn($a,$b)=>($b['score']<=>$a['score'])?:($b['bestStreak']<=>$a['bestStreak'])?:strcmp($a['name'],$b['name']));return $a;}
function public_state(array $r,int $me):array{$status=$r['status'];$card=null;if(in_array($status,['voting','reveal'],true)){$c=current_card($r);$card=['id'=>$c['id'],'name'=>$c['name'],'difficulty'=>$c['difficulty'],'clue'=>$c['clue']];if($status==='reveal'){$card['answer']=$c['answer'];$card['reality']=$c['reality'];$card['source']=$c['source'];}}$players=[];foreach($r['players'] as $i=>$p)$players[]=public_player($p,$status,$i===$me);return ['code'=>$r['code'],'status'=>$status,'serverNow'=>now_ms(),'revision'=>$r['revision'],'round'=>$r['round']+1,'roundLimit'=>$r['roundLimit'],'voteSeconds'=>$r['voteSeconds'],'revealSeconds'=>$r['revealSeconds'],'autoAdvance'=>$r['autoAdvance'],'joinLocked'=>$r['joinLocked'],'voteEndsAt'=>$r['voteEndsAt'],'revealEndsAt'=>$r['revealEndsAt'],'hostId'=>$r['hostId'],'me'=>$players[$me],'players'=>$players,'card'=>$card,'roundSummary'=>$r['roundSummary'],'chat'=>$r['chat'],'standings'=>standings($r['players']),'lastEvent'=>$r['lastEvent'],'finishReason'=>$r['finishReason']??null];}
function validate_setting($v,array $allowed,string $label):int{$n=intval($v);if(!in_array($n,$allowed,true))fail('Invalid '.$label.'.');return $n;}

$action=$_GET['action']??'state';if($_SERVER['REQUEST_METHOD']==='OPTIONS')out([],204);
if($action==='create'&&$_SERVER['REQUEST_METHOD']==='POST'){rate_limit('create',6,60);$b=body();$name=clean_name($b['name']??'');$rounds=validate_setting($b['rounds']??12,BOB_ROUND_OPTIONS,'round count');$vote=validate_setting($b['voteSeconds']??24,BOB_VOTE_OPTIONS,'vote timer');$reveal=validate_setting($b['revealSeconds']??9,BOB_REVEAL_OPTIONS,'reveal timer');do{$code=room_code();$exists=store_get('bob2_room_'.$code);}while($exists);$p=player_new($name,true);presence_touch($p['id']);$deck=cards();$r=['code'=>$code,'status'=>'lobby','hostId'=>$p['id'],'players'=>[$p],'round'=>0,'roundLimit'=>min($rounds,count($deck)),'deckOrder'=>shuffle_idx(count($deck)),'voteSeconds'=>$vote,'revealSeconds'=>$reveal,'autoAdvance'=>!isset($b['autoAdvance'])||!empty($b['autoAdvance']),'joinLocked'=>false,'voteEndsAt'=>null,'revealEndsAt'=>null,'roundSummary'=>null,'chat'=>[],'lastEvent'=>null,'revision'=>0,'createdAt'=>now_ms(),'updatedAt'=>now_ms()];system_msg($r,$name.' opened the room.');room_save($r);out(['code'=>$code,'playerId'=>$p['id'],'token'=>$p['token']]);}
if($action==='join'&&$_SERVER['REQUEST_METHOD']==='POST'){rate_limit('join',30,60);$b=body();$code=code6($b['code']??'');$name=clean_name($b['name']??'');$result=with_lock($code,function()use($code,$name){$r=room_get($code);if($r['status']!=='lobby'||!empty($r['joinLocked']))fail('This lobby is locked.');if(count(active_players($r))>=BOB_MAX_PLAYERS)fail('This room is full.');foreach($r['players'] as $p)if(!empty($p['active'])&&strcasecmp($p['name'],$name)===0)fail('That player name is already in this room.');$p=player_new($name,false);presence_touch($p['id']);$r['players'][]=$p;system_msg($r,$name.' joined the room.');room_save($r);return ['code'=>$code,'playerId'=>$p['id'],'token'=>$p['token']];});out($result);}

$code=code6($_GET['code']??'');
$result=with_lock($code,function()use($action){$r=room_get(code6($_GET['code']??''));$me=auth_room($r);if(!presence_alive($r['hostId'])&&$r['players'][$me]['id']!==$r['hostId']){transfer_host($r);room_save($r);$me=pidx($r,$_SERVER['HTTP_X_PLAYER_ID']??'');}if(advance($r))room_save($r);$p=$r['players'][$me];
if($action==='state'&&$_SERVER['REQUEST_METHOD']==='GET')return public_state($r,$me);
if($action==='settings'&&$_SERVER['REQUEST_METHOD']==='POST'){if($p['id']!==$r['hostId'])fail('Only the host can change settings.',403);if($r['status']!=='lobby')fail('Settings are locked after the game starts.');$b=body();$r['roundLimit']=validate_setting($b['rounds']??$r['roundLimit'],BOB_ROUND_OPTIONS,'round count');$r['voteSeconds']=validate_setting($b['voteSeconds']??$r['voteSeconds'],BOB_VOTE_OPTIONS,'vote timer');$r['revealSeconds']=validate_setting($b['revealSeconds']??$r['revealSeconds'],BOB_REVEAL_OPTIONS,'reveal timer');$r['autoAdvance']=!empty($b['autoAdvance']);room_save($r);return public_state($r,$me);}
if($action==='lock'&&$_SERVER['REQUEST_METHOD']==='POST'){if($p['id']!==$r['hostId'])fail('Only the host can lock the lobby.',403);if($r['status']!=='lobby')fail('The lobby is already closed.');$r['joinLocked']=!$r['joinLocked'];system_msg($r,$r['joinLocked']?'Lobby locked.':'Lobby reopened.');room_save($r);return public_state($r,$me);}
if($action==='start'&&$_SERVER['REQUEST_METHOD']==='POST'){if($p['id']!==$r['hostId'])fail('Only the host can start the game.',403);if($r['status']!=='lobby')fail('The game has already started.');if(count(active_players($r))<BOB_MIN_PLAYERS)fail('At least two players are required.');$r['joinLocked']=true;begin_round($r);system_msg($r,'The game started. Lock in BUD or BLUFF.');room_save($r);return public_state($r,$me);}
